(ROOT/'experiments/project_history.json').write_text(json.dumps(cat,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
topics=read(ROOT/'experiments/obsidian_experiment_topics.json');topics['topics'][card['id']]=['Сохранение личности','Содержание области наблюдения','Различение цели и помех внутри рамки'];(ROOT/'experiments/obsidian_experiment_topics.json').write_text(json.dumps(topics,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
probs=read(ROOT/'experiments/system_problems.json');c=next(x for x in probs['problems'] if x['id']=='С1');c['cases'].append(dict(date='2026-11-14',component='Внешний считыватель масок',fact=card['obtained'],hypothesis='Отсутствие отдельного образца выбранной машины может ограничивать разделение похожих объектов; причинный вклад не измерен.',discriminating_check='Равный контроль без FlyVis, геометрия, три новых для обучения видео, ручные видимые участки.',limitation=card['cannot_claim'],evidence=[rel(OUT/'result.json'),rel(OUT/'audit.json')],source_sha256=sha(OUT/'result.json')));c['cards'].append(card['id']);(ROOT/'experiments/system_problems.json').write_text(json.dumps(probs,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
